def onboarding_profile_setup(request):
    """
    Profile setup step for onboarding.
    """
    if request.method == "POST":
        form = UserProfileForm(request.POST, instance=request.user.profile)
        if form.is_valid():
            form.save()
            # Mark step as complete
            OnboardingService.complete_step(
                request.user, OnboardingService.STEP_PROFILE_SETUP
            )
            messages.success(request, _("Profile updated successfully!"))
            return redirect("onboarding_calendar")
    else:
        form = UserProfileForm(instance=request.user.profile)

    context = {
        "form": form,
        "step_name": OnboardingService.STEP_NAMES[OnboardingService.STEP_PROFILE_SETUP],
        "step_description": OnboardingService.STEP_DESCRIPTIONS[
            OnboardingService.STEP_PROFILE_SETUP
        ],
    }
    return render(request, "users/onboarding/profile_setup.html", context)


