        action = request.POST.get("action")

        if action == "skip":
            # Skip this step
            OnboardingService.complete_step(
                request.user, OnboardingService.STEP_CALENDAR_SYNC
            )
            return redirect("onboarding_calendar")
        elif action == "connect":
