def _get_home_family(user):
    profile = getattr(user, "profile", None)
    if profile and getattr(profile, "primary_family_id", None):
        return profile.primary_family

    membership = (
        FamilyMembership.objects.select_related("family")
        .filter(user=user, family__group_type__type="IMMEDIATE", is_active=True)
        .first()
    )
    if membership:
        return membership.family

    membership = (
        FamilyMembership.objects.select_related("family")
        .filter(user=user, is_active=True)
        .first()
    )
    return membership.family if membership else None


def _complete_family_setup_step(request, step_to_complete, next_url_name):
    OnboardingService.complete_step(request.user, step_to_complete)
    messages.success(request, _("Family setup saved."))
    return redirect(next_url_name)


def _render_family_setup_step(
    request, *, step_to_complete, next_url_name, progress=None
):
    home_family = _get_home_family(request.user)

    if request.method == "POST":
        action = request.POST.get("action")

        if action == "confirm_existing":
            family_name = (request.POST.get("family_name") or "").strip()
            if not home_family:
                messages.error(request, _("Create a home group before continuing."))
            elif not family_name:
                messages.error(request, _("Please enter a home-group name."))
            else:
                if home_family.name != family_name:
                    home_family.name = family_name
                    home_family.save(update_fields=["name"])
                if request.user.profile.primary_family_id != home_family.id:
                    request.user.profile.primary_family = home_family
                    request.user.profile.save(update_fields=["primary_family"])
                return _complete_family_setup_step(
                    request, step_to_complete, next_url_name
                )

        elif action == "create":
            family_name = (request.POST.get("family_name") or "").strip()
            if not family_name:
                messages.error(request, _("Please enter a family name."))
            else:
                with transaction.atomic():
                    family = FamilyGroup.objects.create(name=family_name)
                    FamilyMembership.objects.create(
                        user=request.user,
                        family=family,
                        role="PARENT",
                        is_admin=True,
                    )
                    request.user.profile.primary_family = family
                    request.user.profile.save(update_fields=["primary_family"])
                messages.success(request, _("Family created successfully!"))
                return _complete_family_setup_step(
                    request, step_to_complete, next_url_name
                )

        elif action == "join":
            referral_code = (request.POST.get("referral_code") or "").strip()
            if not referral_code:
                messages.error(request, _("Referral code is required."))
            else:
                try:
                    family = FamilyGroup.objects.get(referral_code=referral_code)
                except FamilyGroup.DoesNotExist:
                    messages.error(request, _("Invalid referral code."))
                else:
                    result = submit_family_join_request(
                        user=request.user, family=family
                    )
                    if result.already_pending:
                        messages.warning(
                            request,
                            _(
                                f"You already have a pending request to join {family.name}."
                            ),
                        )
                    else:
                        messages.success(
                            request,
                            _(
                                f"Your request to join {family.name} has been submitted."
                            ),
                        )
                    return _complete_family_setup_step(
                        request, step_to_complete, next_url_name
                    )

    context = {
        "progress": progress,
        "home_family": home_family,
        "step_name": OnboardingService.STEP_NAMES[step_to_complete],
        "step_description": OnboardingService.STEP_DESCRIPTIONS[step_to_complete],
    }
    return render(request, "users/onboarding/family_connection.html", context)


@login_required
def onboarding_start(request):
    """
    Entry point for user onboarding. Detects persona and redirects accordingly.
    """
    # Check if new onboarding is enabled
    user_context = {"user_id": str(request.user.id), "email": request.user.email}
    if not onboarding_flags.is_new_onboarding_enabled(user_context):
        # Redirect to dashboard if new onboarding is disabled
        return redirect("dashboard")

    # Detect user persona
    persona_type = OnboardingService.detect_user_persona(request.user, request)

    # Store persona in session for future reference
    request.session["onboarding_persona"] = persona_type

    # Redirect based on persona with feature flag checks
    if persona_type == OnboardingService.PERSONA_CALENDAR_ONLY:
        if onboarding_flags.is_calendar_onboarding_enabled(user_context):
            return redirect("onboarding_calendar")
    elif persona_type == OnboardingService.PERSONA_VACATION_PARTICIPANT:
        if onboarding_flags.is_trip_participant_onboarding_enabled(user_context):
            return redirect("onboarding_trip_participant")
    elif persona_type == OnboardingService.PERSONA_VACATION_ADMIN:
        # Use existing trip onboarding
        trip_id = request.session.get("trip_invite_id")
        if trip_id:
            return redirect("trips:onboarding_dashboard", pk=trip_id)
    elif persona_type == OnboardingService.PERSONA_FAMILY_ADMIN:
        if onboarding_flags.is_family_admin_onboarding_enabled(user_context):
            return redirect("onboarding_family_admin")
    elif persona_type == OnboardingService.PERSONA_REGIONAL_DISCOVERY:
        if onboarding_flags.is_regional_discovery_onboarding_enabled(user_context):
            return redirect("onboarding_regional_discovery")
    else:
        return redirect("onboarding_general")

    # Default to dashboard if specific flow is disabled
    return redirect("dashboard")


@login_required
def onboarding_general(request):
    """
    General onboarding flow for users without a specific persona.
    """
    progress = OnboardingService.get_onboarding_progress(
        request.user, OnboardingService.PERSONA_GENERAL
    )

    current_step = progress.get("current_step")
    if not current_step:
        return redirect("onboarding_complete")

    step_id = current_step["step"]
    if step_id == OnboardingService.STEP_PROFILE_SETUP:
        return onboarding_profile_setup(request)
    elif step_id == OnboardingService.STEP_FAMILY_CONNECTION:
        return _render_family_setup_step(
            request,
            step_to_complete=OnboardingService.STEP_FAMILY_CONNECTION,
            next_url_name="onboarding_general",
