def onboarding_trip_quick_start(request):
    """
    Trip quick start - create trip with pre-populated region and saved events.
    """
    from trips.forms import TripForm
    from trips.models import SavedRegionEvent

    discovery_region = getattr(request.user.profile, "discovery_region", None)
    saved_events = SavedRegionEvent.objects.filter(
        user=request.user, added_to_trip__isnull=True
    ).select_related("region_event")

    # Suggest dates based on saved events
    suggested_start = None
    suggested_end = None
    if saved_events.exists():
        event_dates = [se.region_event.start_datetime.date() for se in saved_events]
        suggested_start = min(event_dates)
        suggested_end = max(event_dates)

    if request.method == "POST":
        form = TripForm(request.POST, user=request.user)
        if form.is_valid():
            trip = form.save(commit=False)
            trip.creator = request.user
            trip.save()
            form.save_m2m()

            # Link saved events to trip
            selected_event_ids = request.POST.getlist("saved_events")
            if selected_event_ids:
                SavedRegionEvent.objects.filter(
                    user=request.user, region_event_id__in=selected_event_ids
                ).update(added_to_trip=trip)

            OnboardingService.complete_step(
                request.user, OnboardingService.STEP_TRIP_QUICK_START
            )
            messages.success(
                request, _("Trip created! Now add activities and invite members.")
            )
            return redirect("trips:trip_detail", pk=trip.pk)
    else:
        initial = {}
        if discovery_region:
            initial["region"] = discovery_region
        if suggested_start:
            initial["start_date"] = suggested_start
        if suggested_end:
            initial["end_date"] = suggested_end
        form = TripForm(user=request.user, initial=initial)

    context = {
        "form": form,
        "saved_events": saved_events,
        "discovery_region": discovery_region,
        "step_name": OnboardingService.STEP_NAMES[
            OnboardingService.STEP_TRIP_QUICK_START
        ],
        "step_description": OnboardingService.STEP_DESCRIPTIONS[
            OnboardingService.STEP_TRIP_QUICK_START
        ],
    }
    return render(request, "users/onboarding/trip_quick_start.html", context)
